"""Adapter for synthetic floor plan datasets generated by floor plan tools.

Converts paired synthetic images (PNG, JPG, SVG) and annotation JSONs into
the standardized Qwen-VL chat training format. Also includes a synthetic
mock floor plan generator for rapid testing and pipeline verification.
"""

from __future__ import annotations
import json
import os
import random
from pathlib import Path
from typing import List, Dict, Any, Optional, Union, Tuple
from PIL import Image, ImageDraw, ImageFont

from floorplan_reader.converters.image_preprocessor import (
    load_and_preprocess_floorplan,
    is_svg_file,
)
from floorplan_reader.dataset.cubicasa_parser import DEFAULT_INSTRUCTION


class SyntheticFloorPlanAdapter:
    """Ingests custom datasets from floor plan generator tools."""

    def __init__(self, instruction: str = DEFAULT_INSTRUCTION):
        self.instruction = instruction

    def ingest_paired_directory(
        self,
        data_dir: Union[str, Path],
        output_images_dir: Optional[Union[str, Path]] = None,
    ) -> List[Dict[str, Any]]:
        """Ingest a directory containing paired (image, json) floor plan files.

        Looks for matching stems, e.g. `sample_01.png` and `sample_01.json`, or
        `sample_02.svg` and `sample_02.json`.

        Args:
            data_dir: Directory containing images and JSON annotations.
            output_images_dir: Optional directory to save converted raster images.

        Returns:
            List of conversation dictionaries for Qwen-VL training.
        """
        dir_path = Path(data_dir)
        if not dir_path.is_dir():
            raise FileNotFoundError(f"Data directory not found: {dir_path}")

        samples: List[Dict[str, Any]] = []
        image_extensions = {".png", ".jpg", ".jpeg", ".svg"}

        json_files = list(dir_path.glob("*.json"))
        # Exclude dataset summary jsons
        paired_jsons = [j for j in json_files if j.stem not in ("dataset", "train", "val", "metadata")]

        for j_file in sorted(paired_jsons):
            stem = j_file.stem
            # Find matching image file
            matching_img: Optional[Path] = None
            for ext in image_extensions:
                candidate = dir_path / f"{stem}{ext}"
                if candidate.exists():
                    matching_img = candidate
                    break

            if not matching_img:
                continue

            with open(j_file, "r", encoding="utf-8") as f:
                ann_data = json.load(f)

            sample_entry = self.convert_single_pair(
                image_path=matching_img,
                annotation_dict=ann_data,
                sample_id=stem,
                output_images_dir=output_images_dir,
            )
            if sample_entry:
                samples.append(sample_entry)

        return samples

    def convert_single_pair(
        self,
        image_path: Union[str, Path],
        annotation_dict: Dict[str, Any],
        sample_id: str,
        output_images_dir: Optional[Union[str, Path]] = None,
    ) -> Optional[Dict[str, Any]]:
        """Normalize coordinates in synthetic annotation dict to [0, 1000] and create conversation entry."""
        img_p = Path(image_path)
        vlm_img, orig_size, _ = load_and_preprocess_floorplan(img_p)
        orig_w, orig_h = orig_size

        # Save rasterized / preprocessed image if requested
        if output_images_dir:
            out_d = Path(output_images_dir)
            out_d.mkdir(parents=True, exist_ok=True)
            saved_img_path = str((out_d / f"{sample_id}.png").resolve())
            vlm_img.save(saved_img_path, format="PNG")
        elif is_svg_file(img_p):
            # Must save rasterized version if source was SVG
            out_d = img_p.parent / "rasterized_cache"
            out_d.mkdir(exist_ok=True)
            saved_img_path = str((out_d / f"{sample_id}.png").resolve())
            vlm_img.save(saved_img_path, format="PNG")
        else:
            saved_img_path = str(img_p.resolve())

        # Normalize rooms, doors, windows
        normalized_rooms = self._normalize_elements(annotation_dict.get("rooms", []), orig_w, orig_h, "room")
        normalized_doors = self._normalize_elements(annotation_dict.get("doors", []), orig_w, orig_h, "door")
        normalized_windows = self._normalize_elements(annotation_dict.get("windows", []), orig_w, orig_h, "window")

        target_json = {
            "rooms": normalized_rooms,
            "doors": normalized_doors,
            "windows": normalized_windows,
        }

        return {
            "id": sample_id,
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {"type": "image", "image": saved_img_path},
                        {"type": "text", "text": self.instruction},
                    ],
                },
                {
                    "role": "assistant",
                    "content": [
                        {"type": "text", "text": json.dumps(target_json, indent=2)},
                    ],
                },
            ],
        }

    def _normalize_elements(
        self,
        elements: List[Dict[str, Any]],
        img_w: int,
        img_h: int,
        default_prefix: str,
    ) -> List[Dict[str, Any]]:
        """Flexible coordinate normalizer handling [ymin, xmin, ymax, xmax] or [x, y, w, h]."""
        results = []
        for idx, el in enumerate(elements):
            box = el.get("box_2d") or el.get("bbox") or el.get("coordinates")
            if not box or len(box) != 4:
                continue

            # Detect if box is already normalized [0, 1000]
            # or in 0-1 float, or in absolute pixels
            if all(0 <= v <= 1.0 for v in box):
                # Float normalized 0-1: [ymin, xmin, ymax, xmax]
                ymin = int(round(box[0] * 1000))
                xmin = int(round(box[1] * 1000))
                ymax = int(round(box[2] * 1000))
                xmax = int(round(box[3] * 1000))
            elif any(v > 1000 for v in box) or (img_w > 1000 and any(v > 1000 for v in [img_w, img_h])):
                # Absolute pixels: check if [x, y, w, h] or [ymin, xmin, ymax, xmax]
                if "box_2d" in el and box[0] <= img_h and box[1] <= img_w:
                    # [ymin, xmin, ymax, xmax] in pixels
                    ymin = int(round((box[0] / img_h) * 1000))
                    xmin = int(round((box[1] / img_w) * 1000))
                    ymax = int(round((box[2] / img_h) * 1000))
                    xmax = int(round((box[3] / img_w) * 1000))
                else:
                    # Assume COCO [x, y, w, h]
                    x, y, w, h = box
                    ymin = int(round((y / img_h) * 1000))
                    xmin = int(round((x / img_w) * 1000))
                    ymax = int(round(((y + h) / img_h) * 1000))
                    xmax = int(round(((x + w) / img_w) * 1000))
            else:
                # Already [0, 1000] integer scale
                ymin, xmin, ymax, xmax = int(round(box[0])), int(round(box[1])), int(round(box[2])), int(round(box[3]))

            # Clamp coordinates
            ymin = max(0, min(1000, min(ymin, ymax)))
            xmin = max(0, min(1000, min(xmin, xmax)))
            ymax = max(0, min(1000, max(ymin, ymax)))
            xmax = max(0, min(1000, max(xmin, xmax)))

            entry = dict(el)
            entry["id"] = el.get("id", f"{default_prefix}_{idx + 1}")
            entry["box_2d"] = [ymin, xmin, ymax, xmax]
            # Remove legacy key if present
            if "bbox" in entry:
                del entry["bbox"]
            if "coordinates" in entry:
                del entry["coordinates"]
            results.append(entry)
        return results


def generate_mock_synthetic_sample(
    output_dir: Union[str, Path],
    sample_id: str = "synthetic_plan_001",
    format: str = "svg",
    width: int = 800,
    height: int = 600,
) -> Tuple[Path, Path]:
    """Generates a synthetic floor plan image/SVG and paired JSON annotation.

    Creates a multi-room layout (e.g. Master Bedroom, Bathroom, Kitchen, Living Room)
    with doors, windows, walls, and labels.

    Args:
        output_dir: Destination folder.
        sample_id: Identifier name for the sample files.
        format: 'svg' or 'png'.
        width: Image width in pixels.
        height: Image height in pixels.

    Returns:
        Tuple of (image_file_path, json_file_path).
    """
    out_p = Path(output_dir)
    out_p.mkdir(parents=True, exist_ok=True)

    # 4-room layout coordinates in pixels
    # Margins: 40px
    m = 40
    mid_x = width // 2
    mid_y = height // 2

    rooms_config = [
        {"name": "bedroom", "id": "room_1", "rect": (m, m, mid_x, mid_y), "label": "BEDROOM\n3.6m x 3.2m"},
        {"name": "bathroom", "id": "room_2", "rect": (mid_x, m, width - m, mid_y), "label": "BATHROOM\n2.4m x 1.8m"},
        {"name": "living_room", "id": "room_3", "rect": (m, mid_y, mid_x, height - m), "label": "LIVING ROOM\n4.5m x 4.0m"},
        {"name": "kitchen", "id": "room_4", "rect": (mid_x, mid_y, width - m, height - m), "label": "KITCHEN\n3.2m x 2.8m"},
    ]

    doors_config = [
        {"id": "door_1", "rect": (m + 50, mid_y - 15, m + 80, mid_y + 15), "type": "single_swing"},
        {"id": "door_2", "rect": (mid_x - 15, m + 40, mid_x + 15, m + 70), "type": "single_swing"},
        {"id": "door_3", "rect": (mid_x - 15, mid_y + 40, mid_x + 15, mid_y + 70), "type": "single_swing"},
    ]

    windows_config = [
        {"id": "win_1", "rect": (m + 80, m - 5, m + 160, m + 5), "type": "standard", "wall": "north"},
        {"id": "win_2", "rect": (width - m - 5, m + 60, width - m + 5, m + 140), "type": "standard", "wall": "east"},
        {"id": "win_3", "rect": (m + 60, height - m - 5, m + 160, height - m + 5), "type": "standard", "wall": "south"},
    ]

    # Convert to normalized [0, 1000] target JSON
    target_rooms = []
    for r in rooms_config:
        x1, y1, x2, y2 = r["rect"]
        ymin = int(round((y1 / height) * 1000))
        xmin = int(round((x1 / width) * 1000))
        ymax = int(round((y2 / height) * 1000))
        xmax = int(round((x2 / width) * 1000))
        target_rooms.append({
            "id": r["id"],
            "name": r["name"],
            "box_2d": [ymin, xmin, ymax, xmax],
            "detected_label_text": r["label"].replace("\n", " "),
        })

    target_doors = []
    for d in doors_config:
        x1, y1, x2, y2 = d["rect"]
        ymin = int(round((y1 / height) * 1000))
        xmin = int(round((x1 / width) * 1000))
        ymax = int(round((y2 / height) * 1000))
        xmax = int(round((x2 / width) * 1000))
        target_doors.append({
            "id": d["id"],
            "type": d["type"],
            "box_2d": [ymin, xmin, ymax, xmax],
        })

    target_windows = []
    for w in windows_config:
        x1, y1, x2, y2 = w["rect"]
        ymin = int(round((y1 / height) * 1000))
        xmin = int(round((x1 / width) * 1000))
        ymax = int(round((y2 / height) * 1000))
        xmax = int(round((x2 / width) * 1000))
        target_windows.append({
            "id": w["id"],
            "type": w["type"],
            "wall_side": w["wall"],
            "box_2d": [ymin, xmin, ymax, xmax],
        })

    annotation_payload = {
        "rooms": target_rooms,
        "doors": target_doors,
        "windows": target_windows,
    }

    json_file = out_p / f"{sample_id}.json"
    with open(json_file, "w", encoding="utf-8") as f:
        json.dump(annotation_payload, f, indent=2)

    if format.lower() == "svg":
        img_file = out_p / f"{sample_id}.svg"
        svg_content = f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" width="{width}" height="{height}">
  <rect width="{width}" height="{height}" fill="#fcfcfc"/>
  <!-- Exterior Walls -->
  <rect x="{m}" y="{m}" width="{width - 2*m}" height="{height - 2*m}" fill="none" stroke="#222222" stroke-width="6"/>
  <!-- Interior Dividing Walls -->
  <line x1="{mid_x}" y1="{m}" x2="{mid_x}" y2="{height - m}" stroke="#333333" stroke-width="4"/>
  <line x1="{m}" y1="{mid_y}" x2="{width - m}" y2="{mid_y}" stroke="#333333" stroke-width="4"/>
  <!-- Labels -->
  <text x="{m + 40}" y="{m + 80}" font-family="sans-serif" font-size="16" fill="#111111" font-weight="bold">BEDROOM</text>
  <text x="{mid_x + 40}" y="{m + 80}" font-family="sans-serif" font-size="16" fill="#111111" font-weight="bold">BATHROOM</text>
  <text x="{m + 40}" y="{mid_y + 80}" font-family="sans-serif" font-size="16" fill="#111111" font-weight="bold">LIVING ROOM</text>
  <text x="{mid_x + 40}" y="{mid_y + 80}" font-family="sans-serif" font-size="16" fill="#111111" font-weight="bold">KITCHEN</text>
  <!-- Doors -->
  <rect x="{m + 50}" y="{mid_y - 5}" width="30" height="10" fill="#ffffff" stroke="#c0392b" stroke-width="3"/>
  <rect x="{mid_x - 5}" y="{m + 40}" width="10" height="30" fill="#ffffff" stroke="#c0392b" stroke-width="3"/>
  <rect x="{mid_x - 5}" y="{mid_y + 40}" width="10" height="30" fill="#ffffff" stroke="#c0392b" stroke-width="3"/>
  <!-- Windows -->
  <line x1="{m + 80}" y1="{m}" x2="{m + 160}" y2="{m}" stroke="#2980b9" stroke-width="8"/>
  <line x1="{width - m}" y1="{m + 60}" x2="{width - m}" y2="{m + 140}" stroke="#2980b9" stroke-width="8"/>
  <line x1="{m + 60}" y1="{height - m}" x2="{m + 160}" y2="{height - m}" stroke="#2980b9" stroke-width="8"/>
</svg>"""
        img_file.write_text(svg_content, encoding="utf-8")
    else:
        img_file = out_p / f"{sample_id}.png"
        img = Image.new("RGB", (width, height), color=(252, 252, 252))
        draw = ImageDraw.Draw(img)
        # Exterior walls
        draw.rectangle([m, m, width - m, height - m], outline=(34, 34, 34), width=6)
        # Interior walls
        draw.line([(mid_x, m), (mid_x, height - m)], fill=(51, 51, 51), width=4)
        draw.line([(m, mid_y), (width - m, mid_y)], fill=(51, 51, 51), width=4)
        # Text
        draw.text((m + 40, m + 80), "BEDROOM", fill=(17, 17, 17))
        draw.text((mid_x + 40, m + 80), "BATHROOM", fill=(17, 17, 17))
        draw.text((m + 40, mid_y + 80), "LIVING ROOM", fill=(17, 17, 17))
        draw.text((mid_x + 40, mid_y + 80), "KITCHEN", fill=(17, 17, 17))
        # Windows
        draw.line([(m + 80, m), (m + 160, m)], fill=(41, 128, 185), width=8)
        draw.line([(width - m, m + 60), (width - m, m + 140)], fill=(41, 128, 185), width=8)
        draw.line([(m + 60, height - m), (m + 160, height - m)], fill=(41, 128, 185), width=8)
        img.save(img_file, format="PNG")

    return img_file, json_file


def generate_mock_synthetic_dataset(
    output_dir: Union[str, Path],
    num_samples: int = 10,
    format: str = "svg",
) -> List[Tuple[Path, Path]]:
    """Generate multiple mock floor plan samples for pipeline testing."""
    samples = []
    for i in range(1, num_samples + 1):
        sid = f"synthetic_floorplan_{i:03d}"
        img_p, j_p = generate_mock_synthetic_sample(output_dir, sample_id=sid, format=format)
        samples.append((img_p, j_p))
    return samples
